mapper.select:
SELECT T.username, T.nickname, T.mobile, T.email, T.enabled, T.jobno FROM LA_USERS T



            T.owner = #{parameters.tenantId}


            T.owner IS NULL




            AND T.username NOT IN (SELECT userid FROM LA_USER_ROLES WHERE authority IN ('ROLE_DEV','ROLE_TENANT','ROLE_SYSTEM'))


            AND T.username NOT IN (SELECT userid FROM LA_USER_ROLES WHERE AUTHORITY = 'ROLE_TENANT')



        AND T.username IN (SELECT userid FROM LA_USER_ROLES WHERE authority = #{parameters.authority})


        AND T.username IN #{item}


        AND T.nickname LIKE #{parameters.nickname}


        AND T.mobile LIKE #{parameters.mobile}


        AND T.email LIKE #{parameters.email}


        AND T.username IN (SELECT userid FROM LA_USER_ORGANIZATION WHERE organizationid IN #{item})


        AND T.username IN (SELECT username FROM LA_USER_FIELDS WHERE

            field_name = #{item.fieldName} AND field_value = #{item.fieldValue}


            GROUP BY username HAVING COUNT(1) = #{parameters.personal.size}
        )




                AND T.USERNAME IN (SELECT USERNAME FROM LA_ONLINE_LOG WHERE ON_LINE = 1)


                AND T.USERNAME NOT IN (SELECT USERNAME FROM LA_ONLINE_LOG WHERE ON_LINE = 1)




ORDER BY T.CREATEDATE DESC, T.USERNAME

SELECT T5.USERNAME FROM (SELECT T.AUTHORITY, T.ALIAS FROM LA_ROLES T ) T1 LEFT JOIN (SELECT T3.USERNAME, T2.AUTHORITY, T4.ORGANIZATIONID AS ORGID, T3.NICKNAME FROM LA_USER_ROLES T2 INNER JOIN la_users T3 ON T2.USERID = T3.USERNAME INNER JOIN la_user_organization T4 ON T3.USERNAME = T4.USERID) T5 ON T1.AUTHORITY = T5.AUTHORITY
T1.AUTHORITY = #{authority}
AND T5.ORGID = #{orgId}

mapper.update:
UPDATE LA_USERS SET
    nickname = #{nickname},
    mobile = #{mobile, jdbcType=VARCHAR},
    email = #{email, jdbcType=VARCHAR},
    EXPIRED_TIME = #{expiredTime, jdbcType=TIMESTAMP}

        ,tenantId = #{tenantId, jdbcType=VARCHAR}


        ,jobno = #{jobno, jdbcType=VARCHAR}

WHERE username = #{username}

mapper.select:
SELECT T.username FROM LA_USERS T
INNER JOIN LA_USER_ROLES UR ON UR.userid = T.username
INNER JOIN LA_USER_ORGANIZATION UO ON T.username = UO.userid
WHERE UO.ORGANIZATIONID = #{orgId}

    AND UR.AUTHORITY = #{roleId}

SELECT T.RESOURCEID,T.LA_MANAGE FROM LA_ROLE_RESOURCES T


        T.AUTHORITY = #{authority}


        AND T.LA_MANAGE = #{manage}


        AND T.RESOURCEID IN

            #{item}



group by T.RESOURCEID,T.LA_MANAGE

SELECT DISTINCT T1.USERNAME, T1.NICKNAME FROM LA_USERS T1 LEFT JOIN LA_USER_ORGANIZATION T2 ON T1.USERNAME = T2.USERID
T1.TENANT_ID = #{tenantId}
AND T2.ORGANIZATIONID IN
#{item}

SELECT USERNAME FROM LA_USERS T1 INNER JOIN LA_USER_ORGANIZATION T2 ON T1.USERNAME = T2.USERID


        T2.ORGANIZATIONID IN (SELECT T.ID FROM LA_ORGANIZATION T WHERE T.PARENTKEYS LIKE CONCAT(CONCAT('%', #{orgId}), '%') OR T.ID = #{orgId})


       and T2.ORGANIZATIONID = #{orgId}

SELECT DISTINCT(T.username), T.nickname, T.mobile, T.email, T.enabled, T.jobno,T.createDate, mi.userid, mi.avatar, mi.remark, mi.identity_id , mi.group_no , mi.line_no, mi.position , mi.status, mi.fila_no, mi.emp_no, mi.dd_no, mi.wechat_no, mi.isupdatepwd, o.orgid, o.alias as orgalias, r.authority, r.alias, mi.extend_param, TC.NICKNAME CREATOR FROM LA_USERS T LEFT JOIN LA_USER_INFO mi ON T.username = mi.userid LEFT JOIN (SELECT ur.AUTHORITY,mr.ALIAS,ur.USERID FROM la_user_roles ur LEFT JOIN la_roles mr ON ur.AUTHORITY = mr.AUTHORITY) R ON T.USERNAME = R.USERID LEFT JOIN (SELECT mo.id orgId, mo.organization, uo.userid, mo.alias FROM LA_USER_ORGANIZATION uo LEFT JOIN la_organization mo ON uo.ORGANIZATIONID = mo.id WHERE mo.id is not null) O ON T.USERNAME = O.USERID LEFT JOIN (SELECT NICKNAME, USERNAME FROM LA_USERS) TC ON T.CREATOR = TC.USERNAME
LEFT JOIN LA_USER_ROLES UR ON UR.USERID = T.USERNAME
INNER JOIN ( SELECT USERNAME,
MAX(CASE FIELD_NAME WHEN #{item.fieldName} then field_value ELSE '' END) AS ${item.fieldName},
count(*) NUMS FROM LA_USER_FIELDS GROUP BY USERNAME ) A ON T.USERNAME = A.USERNAME AND
A.${item.fieldName} = #{item.fieldValue}
T.owner = #{parameters.tenantId}
T.owner is null
AND T.username IN #{item}
AND T.username NOT IN (SELECT userid FROM LA_USER_ROLES WHERE authority IN ('ROLE_DEV', 'ROLE_SYSTEM') or AUTHORITY LIKE 'ROLE_TENANT@%')
AND T.username NOT IN (SELECT userid FROM LA_USER_ROLES WHERE AUTHORITY LIKE 'ROLE_TENANT@%')
AND T.nickname LIKE #{parameters.nickname}
AND T.mobile LIKE #{parameters.mobile}
AND T.email LIKE #{parameters.email}
AND UR.authority = #{parameters.authority}
AND O.orgId IN #{item}
ORDER BY T.CREATEDATE DESC, username asc
